INSERT INTO INT_SERVERFUNCTION (ID, NAME, DESCRIPTION, TYPE, CODE, JDBC_ID, PUBLIC_EXECUTION, CRON_EXPRESSION, CRON_INPUT_JSON, CREATED_BY) VALUES (131, 'hotRegrasBase', 'Mount de Regras Contabeis em 1 ida (CRS,CONTAS,CR_CONTAS,GESTORES_CR,DRIVERS,CONTA_DRIVERS,EXCECOES). Sem params.', 'SQL', 'SELECT
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''CODIGO'',t.CODIGO,''NOME'',t.NOME,''EMPRESA_ID'',t.EMPRESA_ID,''ATIVO'',t.ATIVO)) FROM CENTRO_RESULTADO t WHERE t.ATIVO = ''true''),JSON_ARRAY()) AS CRS, COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''CODIGO'',t.CODIGO,''NOME'',t.NOME,''TIPO'',t.TIPO,''NATUREZA'',t.NATUREZA,''ATIVO'',t.ATIVO)) FROM CONTA_CONTABIL t WHERE 1=1),JSON_ARRAY()) AS CONTAS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''CR_ID'',t.CR_ID,''CONTA_ID'',t.CONTA_ID,''ATIVO'',t.ATIVO,''CRIADO_EM'',t.CRIADO_EM)) FROM CR_CONTA t WHERE t.ATIVO = true),JSON_ARRAY()) AS CR_CONTAS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''CR_ID'',x.CR_ID,''GESTORES'',x.GESTORES)) FROM (SELECT gc.CR_ID, GROUP_CONCAT(g.NOME ORDER BY g.NOME SEPARATOR '', '') AS GESTORES FROM GESTOR_CR gc JOIN GESTOR g ON g.ID = gc.GESTOR_ID WHERE g.ATIVO = ''true'' GROUP BY gc.CR_ID) x),JSON_ARRAY()) AS GESTORES_CR,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''NOME'',t.NOME,''DESCRICAO'',t.DESCRICAO,''COR'',t.COR,''ATIVO'',t.ATIVO,''CRIADO_EM'',t.CRIADO_EM,''TIPO_DRIVER'',t.TIPO_DRIVER,''ORIGEM'',t.ORIGEM)) FROM DRIVERS t WHERE t.ATIVO = ''true''),JSON_ARRAY()) AS DRIVERS, COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''CONTA_ID'',t.CONTA_ID,''DRIVER_ID'',t.DRIVER_ID,''CRIADO_EM'',t.CRIADO_EM,''PACOTE_ID'',t.PACOTE_ID)) FROM CONTA_DRIVER t WHERE 1=1),JSON_ARRAY()) AS CONTA_DRIVERS, COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''CR_ID'',t.CR_ID,''CONTA_ID'',t.CONTA_ID,''DRIVER_ID'',t.DRIVER_ID,''ATIVO'',t.ATIVO,''CRIADO_EM'',t.CRIADO_EM,''PACOTE_ID'',t.PACOTE_ID)) FROM CONTA_DRIVER_EXCECAO t WHERE t.ATIVO = true),JSON_ARRAY()) AS EXCECOES', NULL, FALSE, NULL, NULL, 'sarah@mitralab.io');
